\set a 0
BEGIN ISOLATION LEVEL READ COMMITTED;
SET LOCAL jit = off;
SET LOCAL plan_cache_mode = force_generic_plan;
SET LOCAL enable_sort = off;
SET LOCAL enable_bitmapscan = off;
WITH worker_info AS ( SELECT COALESCE((SELECT labels FROM harvest_workers WHERE worker_id = :w), '{}'::jsonb) AS labels ), paused_queues AS MATERIALIZED ( SELECT COALESCE(array_agg(queue_name), ARRAY[]::text[]) AS names FROM harvest_queue_pauses WHERE queue_name = ANY(:q) ), paused_activities AS MATERIALIZED ( SELECT COALESCE(array_agg(activity_name), ARRAY[]::text[]) AS names FROM harvest_activity_pauses ), expired_runs AS MATERIALIZED ( SELECT id FROM harvest_workflow_executions WHERE state = 'RUNNING' AND deadline_at < NOW() UNION ALL SELECT id FROM harvest_workflow_executions WHERE state = 'RUNNING' AND chain_deadline_at < NOW() ), seek_heads AS MATERIALIZED ( SELECT h.seek_id, h.seek_ctid, h.seek_rank, h.seek_priority, h.seek_due, h.seek_pinned, h.seek_concurrency_key, h.seek_concurrency_cap, h.seek_task_type, h.head_queue, h.head_kind, h.head_new_start, row_number() OVER ( PARTITION BY h.head_queue, h.head_kind, h.head_new_start ORDER BY h.seek_priority DESC, h.seek_due ASC ) AS seek_rn FROM ( SELECT s.*, FALSE AS seek_pinned, q.name AS head_queue, k.head_kind, k.new_start_head AS head_new_start FROM (SELECT DISTINCT name FROM unnest(:q::text[]) AS u(name)) AS q CROSS JOIN paused_queues CROSS JOIN paused_activities CROSS JOIN (VALUES ('workflow', FALSE), ('workflow', TRUE), ('activity', FALSE), ('activity', TRUE)) AS k(head_kind, new_start_head) CROSS JOIN LATERAL ( SELECT id AS seek_id, ctid AS seek_ctid, CASE WHEN sticky_worker_id = :w AND sticky_until > NOW() THEN 1 ELSE 0 END AS seek_rank, priority AS seek_priority, (scheduled_at + CASE WHEN new_start AND attempt = 0 THEN INTERVAL '30 seconds' ELSE INTERVAL '0 seconds' END) AS seek_due, concurrency_key AS seek_concurrency_key, concurrency_cap AS seek_concurrency_cap, task_type AS seek_task_type FROM harvest_task_queue WHERE queue_name = q.name AND task_type = k.head_kind AND state = 'PENDING' AND (new_start AND attempt = 0) >= k.new_start_head AND (new_start AND attempt = 0) <= k.new_start_head AND scheduled_at <= NOW() AND ( schedule_to_close_at IS NULL OR schedule_to_close_at > NOW() ) AND ( sticky_worker_id IS NULL OR sticky_worker_id = :w OR sticky_until IS NULL OR sticky_until <= NOW() ) AND ( session_id IS NULL OR sticky_worker_id = :w ) AND CASE WHEN task_type = 'activity' AND activity_name = ANY(paused_activities.names) THEN FALSE WHEN task_type = 'activity' AND required_capabilities IS NULL AND activity_name = ANY(:m) THEN FALSE WHEN task_type = 'activity' AND activity_name = ANY(ARRAY( SELECT substr(marked, 2) FROM unnest(:m::text[]) AS marked WHERE left(marked, 1) = chr(1) )) THEN FALSE ELSE TRUE END ORDER BY (new_start AND attempt = 0), priority DESC, scheduled_at ASC LIMIT 32 ) s WHERE NOT (q.name = ANY(paused_queues.names)) UNION ALL SELECT p.*, TRUE, NULL, NULL, NULL FROM paused_queues CROSS JOIN paused_activities CROSS JOIN LATERAL ( SELECT * FROM ( SELECT id AS seek_id, ctid AS seek_ctid, CASE WHEN sticky_worker_id = :w AND sticky_until > NOW() THEN 1 ELSE 0 END AS seek_rank, priority AS seek_priority, (scheduled_at + CASE WHEN new_start AND attempt = 0 THEN INTERVAL '30 seconds' ELSE INTERVAL '0 seconds' END) AS seek_due, concurrency_key AS seek_concurrency_key, concurrency_cap AS seek_concurrency_cap, task_type AS seek_task_type FROM harvest_task_queue WHERE sticky_worker_id >= :w AND sticky_worker_id <= :w AND harvest_task_queue.state = 'PENDING' AND queue_name = ANY(:q) AND sticky_until > NOW() AND scheduled_at <= NOW() AND NOT (queue_name = ANY(paused_queues.names)) AND ( schedule_to_close_at IS NULL OR schedule_to_close_at > NOW() ) AND ( sticky_worker_id IS NULL OR sticky_worker_id = :w OR sticky_until IS NULL OR sticky_until <= NOW() ) AND ( session_id IS NULL OR sticky_worker_id = :w ) AND CASE WHEN task_type = 'activity' AND activity_name = ANY(paused_activities.names) THEN FALSE WHEN task_type = 'activity' AND required_capabilities IS NULL AND activity_name = ANY(:m) THEN FALSE WHEN task_type = 'activity' AND activity_name = ANY(ARRAY( SELECT substr(marked, 2) FROM unnest(:m::text[]) AS marked WHERE left(marked, 1) = chr(1) )) THEN FALSE ELSE TRUE END ORDER BY sticky_worker_id, queue_name, priority DESC, scheduled_at OFFSET 0 ) pins ORDER BY seek_priority DESC, seek_due ASC LIMIT 32 ) p ) h WHERE :a::BIGINT IS NULL OR :a::BIGINT <= 0 ), seek_bounds AS MATERIALIZED ( SELECT seek_pinned AS bound_pinned, seek_priority AS bound_priority, seek_due AS bound_due, head_queue AS bound_queue, head_kind AS bound_kind, head_new_start AS bound_new_start FROM seek_heads WHERE seek_rn = 32 ), seek_pending_keys AS MATERIALIZED ( SELECT DISTINCT seek_concurrency_key AS concurrency_key, seek_task_type AS task_type FROM seek_heads WHERE seek_concurrency_key IS NOT NULL AND seek_concurrency_cap IS NOT NULL ), seek_running_counts AS MATERIALIZED ( SELECT t.concurrency_key, t.task_type, COUNT(*) AS running_count FROM harvest_task_queue t WHERE t.state = 'RUNNING' AND t.worker_id IS NOT NULL AND t.concurrency_key IN (SELECT concurrency_key FROM seek_pending_keys) GROUP BY t.concurrency_key, t.task_type ), seek_candidate AS ( SELECT id, task_type, concurrency_key, concurrency_cap, rate_limit_key, activity_name, workflow_exec_id FROM harvest_task_queue CROSS JOIN worker_info CROSS JOIN paused_queues CROSS JOIN paused_activities WHERE harvest_task_queue.state = (SELECT 'PENDING'::text) AND scheduled_at <= NOW() AND NOT (harvest_task_queue.queue_name = ANY(paused_queues.names)) AND harvest_task_queue.ctid = ANY(ARRAY( SELECT w.seek_ctid FROM seek_heads w WHERE NOT EXISTS (SELECT 1 FROM seek_bounds b WHERE (b.bound_pinned OR w.seek_rank = 0) AND ( (b.bound_pinned AND w.seek_rank = 0) OR w.seek_priority < b.bound_priority OR (w.seek_priority = b.bound_priority AND w.seek_due > b.bound_due) ) ) )) AND ( schedule_to_close_at IS NULL OR schedule_to_close_at > NOW() ) AND ( sticky_worker_id IS NULL OR sticky_worker_id = :w OR sticky_until IS NULL OR sticky_until <= NOW() ) AND ( session_id IS NULL OR sticky_worker_id = :w ) AND ( task_type != 'activity' OR activity_name IS NULL OR required_capabilities IS NOT NULL OR NOT (activity_name = ANY(:m)) ) AND ( task_type != 'activity' OR activity_name IS NULL OR NOT (activity_name = ANY(ARRAY( SELECT substr(marked, 2) FROM unnest(:m::text[]) AS marked WHERE left(marked, 1) = chr(1) ))) ) AND ( task_type != 'activity' OR activity_name IS NULL OR NOT (activity_name = ANY(paused_activities.names)) ) AND ( concurrency_key IS NULL OR concurrency_cap IS NULL OR COALESCE(( SELECT rc.running_count FROM seek_running_counts rc WHERE rc.concurrency_key = harvest_task_queue.concurrency_key AND rc.task_type = harvest_task_queue.task_type ), 0) < harvest_task_queue.concurrency_cap ) AND ( required_build_id IS NULL OR (''::text <> '' AND ( required_build_id = ''::text OR EXISTS ( SELECT 1 FROM harvest_build_compat WHERE build_id = ''::text AND compatible_with = harvest_task_queue.required_build_id ) )) ) AND ( task_type <> 'workflow' OR workflow_exec_id IS NULL OR NOT EXISTS ( SELECT 1 FROM harvest_workflow_executions e WHERE e.id = harvest_task_queue.workflow_exec_id AND e.state = 'PAUSED' ) ) AND ( workflow_exec_id IS NULL OR NOT EXISTS ( SELECT 1 FROM expired_runs x WHERE x.id = harvest_task_queue.workflow_exec_id ) ) AND ( required_capabilities IS NULL OR NOT EXISTS ( SELECT 1 FROM jsonb_array_elements(required_capabilities) AS r(value) WHERE ( r.value ? 'Exact' AND ( worker_info.labels->>(r.value->'Exact'->>'key') IS NULL OR worker_info.labels->>(r.value->'Exact'->>'key') != (r.value->'Exact'->>'value') ) ) OR ( r.value ? 'In' AND ( worker_info.labels->>(r.value->'In'->>'key') IS NULL OR NOT ( (r.value->'In'->'values') @> jsonb_build_array(worker_info.labels->>(r.value->'In'->>'key')) ) ) ) ) ) AND ( rate_limit_key IS NULL OR harvest_task_queue.activity_name = ANY(:r) OR EXISTS ( SELECT 1 FROM harvest_rate_limit_buckets b WHERE b.key = harvest_task_queue.rate_limit_key AND LEAST(COALESCE(CASE WHEN b.override_expires_at > NOW() THEN b.override_burst ELSE NULL END, b.burst), b.tokens + GREATEST(0, EXTRACT(EPOCH FROM (LEAST(COALESCE(b.override_expires_at, b.last_refilled_at), NOW()) - b.last_refilled_at))) * COALESCE(b.override_refill_rate, b.refill_rate) + GREATEST(0, EXTRACT(EPOCH FROM (NOW() - GREATEST(COALESCE(b.override_expires_at, b.last_refilled_at), b.last_refilled_at)))) * b.refill_rate) >= 1.0 ) ) ORDER BY CASE WHEN sticky_worker_id = :w AND sticky_until > NOW() THEN 1 ELSE 0 END DESC, CASE WHEN :a::BIGINT IS NOT NULL AND :a::BIGINT > 0 THEN priority + FLOOR(EXTRACT(EPOCH FROM (NOW() - scheduled_at)) / :a::BIGINT)::INT ELSE priority END DESC, (scheduled_at + CASE WHEN new_start AND attempt = 0 THEN INTERVAL '30 seconds' ELSE INTERVAL '0 seconds' END) ASC LIMIT 1 FOR UPDATE SKIP LOCKED ), seek_held AS MATERIALIZED ( SELECT id, task_type, concurrency_key, concurrency_cap, rate_limit_key, activity_name, workflow_exec_id FROM harvest_task_queue CROSS JOIN worker_info CROSS JOIN paused_queues CROSS JOIN paused_activities WHERE harvest_task_queue.state = (SELECT 'PENDING'::text) AND scheduled_at <= NOW() AND NOT (harvest_task_queue.queue_name = ANY(paused_queues.names)) AND harvest_task_queue.ctid = ANY(ARRAY( SELECT w.seek_ctid FROM seek_heads w WHERE NOT EXISTS (SELECT 1 FROM seek_bounds b WHERE (b.bound_pinned OR w.seek_rank = 0) AND ( (b.bound_pinned AND w.seek_rank = 0) OR w.seek_priority < b.bound_priority OR (w.seek_priority = b.bound_priority AND w.seek_due > b.bound_due) ) ) )) AND NOT EXISTS (SELECT 1 FROM seek_candidate) AND ( schedule_to_close_at IS NULL OR schedule_to_close_at > NOW() ) AND ( sticky_worker_id IS NULL OR sticky_worker_id = :w OR sticky_until IS NULL OR sticky_until <= NOW() ) AND ( session_id IS NULL OR sticky_worker_id = :w ) AND ( task_type != 'activity' OR activity_name IS NULL OR required_capabilities IS NOT NULL OR NOT (activity_name = ANY(:m)) ) AND ( task_type != 'activity' OR activity_name IS NULL OR NOT (activity_name = ANY(ARRAY( SELECT substr(marked, 2) FROM unnest(:m::text[]) AS marked WHERE left(marked, 1) = chr(1) ))) ) AND ( task_type != 'activity' OR activity_name IS NULL OR NOT (activity_name = ANY(paused_activities.names)) ) AND ( concurrency_key IS NULL OR concurrency_cap IS NULL OR COALESCE(( SELECT rc.running_count FROM seek_running_counts rc WHERE rc.concurrency_key = harvest_task_queue.concurrency_key AND rc.task_type = harvest_task_queue.task_type ), 0) < harvest_task_queue.concurrency_cap ) AND ( required_build_id IS NULL OR (''::text <> '' AND ( required_build_id = ''::text OR EXISTS ( SELECT 1 FROM harvest_build_compat WHERE build_id = ''::text AND compatible_with = harvest_task_queue.required_build_id ) )) ) AND ( task_type <> 'workflow' OR workflow_exec_id IS NULL OR NOT EXISTS ( SELECT 1 FROM harvest_workflow_executions e WHERE e.id = harvest_task_queue.workflow_exec_id AND e.state = 'PAUSED' ) ) AND ( workflow_exec_id IS NULL OR NOT EXISTS ( SELECT 1 FROM expired_runs x WHERE x.id = harvest_task_queue.workflow_exec_id ) ) AND ( required_capabilities IS NULL OR NOT EXISTS ( SELECT 1 FROM jsonb_array_elements(required_capabilities) AS r(value) WHERE ( r.value ? 'Exact' AND ( worker_info.labels->>(r.value->'Exact'->>'key') IS NULL OR worker_info.labels->>(r.value->'Exact'->>'key') != (r.value->'Exact'->>'value') ) ) OR ( r.value ? 'In' AND ( worker_info.labels->>(r.value->'In'->>'key') IS NULL OR NOT ( (r.value->'In'->'values') @> jsonb_build_array(worker_info.labels->>(r.value->'In'->>'key')) ) ) ) ) ) AND ( rate_limit_key IS NULL OR harvest_task_queue.activity_name = ANY(:r) OR EXISTS ( SELECT 1 FROM harvest_rate_limit_buckets b WHERE b.key = harvest_task_queue.rate_limit_key AND LEAST(COALESCE(CASE WHEN b.override_expires_at > NOW() THEN b.override_burst ELSE NULL END, b.burst), b.tokens + GREATEST(0, EXTRACT(EPOCH FROM (LEAST(COALESCE(b.override_expires_at, b.last_refilled_at), NOW()) - b.last_refilled_at))) * COALESCE(b.override_refill_rate, b.refill_rate) + GREATEST(0, EXTRACT(EPOCH FROM (NOW() - GREATEST(COALESCE(b.override_expires_at, b.last_refilled_at), b.last_refilled_at)))) * b.refill_rate) >= 1.0 ) ) ), seek_contended AS MATERIALIZED ( SELECT DISTINCT w.head_queue, w.head_kind, w.head_new_start FROM seek_heads w JOIN seek_held x ON x.id = w.seek_id WHERE w.head_queue IS NOT NULL ), candidate AS ( SELECT * FROM seek_candidate ), fresh_now AS MATERIALIZED ( SELECT clock_timestamp() AS ts FROM (SELECT 1 AS one) base LEFT JOIN ( SELECT 1 AS x FROM harvest_rate_limit_buckets b JOIN candidate c ON b.key = c.rate_limit_key WHERE NOT (c.activity_name = ANY(:r)) FOR UPDATE OF b ) locked ON TRUE ), run_expired_now AS MATERIALIZED ( SELECT EXISTS ( SELECT 1 FROM candidate c JOIN harvest_workflow_executions e ON e.id = c.workflow_exec_id WHERE e.state = 'RUNNING' AND (e.deadline_at < (SELECT ts FROM fresh_now) OR e.chain_deadline_at < (SELECT ts FROM fresh_now)) ) AS expired ), rate_limit_debit AS ( UPDATE harvest_rate_limit_buckets b SET tokens = LEAST(COALESCE(CASE WHEN b.override_expires_at > NOW() THEN b.override_burst ELSE NULL END, b.burst), b.tokens + GREATEST(0, EXTRACT(EPOCH FROM (LEAST(COALESCE(b.override_expires_at, b.last_refilled_at), NOW()) - b.last_refilled_at))) * COALESCE(b.override_refill_rate, b.refill_rate) + GREATEST(0, EXTRACT(EPOCH FROM (NOW() - GREATEST(COALESCE(b.override_expires_at, b.last_refilled_at), b.last_refilled_at)))) * b.refill_rate) - 1.0, last_refilled_at = NOW() FROM candidate WHERE b.key = candidate.rate_limit_key AND NOT (candidate.activity_name = ANY(:r)) AND NOT (SELECT expired FROM run_expired_now) AND LEAST(COALESCE(CASE WHEN b.override_expires_at > NOW() THEN b.override_burst ELSE NULL END, b.burst), b.tokens + GREATEST(0, EXTRACT(EPOCH FROM (LEAST(COALESCE(b.override_expires_at, b.last_refilled_at), NOW()) - b.last_refilled_at))) * COALESCE(b.override_refill_rate, b.refill_rate) + GREATEST(0, EXTRACT(EPOCH FROM (NOW() - GREATEST(COALESCE(b.override_expires_at, b.last_refilled_at), b.last_refilled_at)))) * b.refill_rate) >= 1.0 RETURNING b.key AS debited_key ), claimed AS ( UPDATE harvest_task_queue SET state = 'RUNNING', worker_id = :w, started_at = NOW(), attempt = attempt + 1, wake_requested = FALSE FROM candidate WHERE harvest_task_queue.id = candidate.id AND ( candidate.concurrency_key IS NULL OR ( pg_try_advisory_xact_lock(hashtext(candidate.concurrency_key)::bigint) AND ( candidate.concurrency_cap IS NULL OR ( SELECT COUNT(*) FROM harvest_task_queue recheck WHERE recheck.concurrency_key = candidate.concurrency_key AND recheck.task_type = candidate.task_type AND recheck.state = 'RUNNING' AND recheck.worker_id IS NOT NULL ) < candidate.concurrency_cap ) ) ) AND ( candidate.rate_limit_key IS NULL OR candidate.activity_name = ANY(:r) OR EXISTS (SELECT 1 FROM rate_limit_debit WHERE debited_key = candidate.rate_limit_key) ) AND NOT (SELECT expired FROM run_expired_now) RETURNING harvest_task_queue.* ) SELECT claimed.id, claimed.queue_name, claimed.task_type, claimed.workflow_exec_id, claimed.activity_name, claimed.activity_id, claimed.input, claimed.state, claimed.priority, claimed.worker_id, claimed.attempt, claimed.max_attempts, claimed.scheduled_at, claimed.started_at, claimed.completed_at, claimed.last_heartbeat_at, claimed.heartbeat_details, claimed.heartbeat_timeout, claimed.start_to_close, claimed.schedule_to_start, claimed.retry_policy, claimed.output, claimed.error, claimed.sticky_worker_id, claimed.sticky_until, claimed.sticky_timeout, claimed.trace_context, claimed.concurrency_key, claimed.concurrency_cap, claimed.required_build_id, claimed.rate_limit_key, claimed.crash_strikes, claimed.schedule_to_close_at, claimed.required_capabilities, claimed.context_headers, claimed.created_at, claimed.wake_requested, claimed.session_id, claimed.capability_misses, claimed.capability_miss_workers, claimed.capability_miss_handler, claimed.timer_fires_at, claimed.handler_started_attempt, claimed.timed_out_claims, claimed.handler_started_at, claimed.new_start, claimed.fairness_key FROM claimed;
ROLLBACK;
